<?php
require 'includes/config.php';
$u = require_login(); $id = $u['id']; $role = $u['role'];
$ann = all("SELECT * FROM announcements ORDER BY id DESC LIMIT 3");
$title = 'Dashboard'; include 'includes/header.php';
function kpi($ic, $n, $l, $solid = false){ echo '<div class="kpi'.($solid ? ' solid' : '').'"><div class="ic">'.$ic.'</div><div><h3>'.$n.'</h3><p>'.$l.'</p></div></div>'; }
?>
<div class="card welcome"><h2 style="color:#fff">Hello, <?= e(explode(' ', $u['name'])[0]) ?> 👋</h2><p style="color:#d8f5e3">Welcome to Telesom LearnHub — <?= ['learner' => 'keep learning and earn your next certificate.', 'instructor' => 'here is how your courses are doing.', 'admin' => 'here is an overview of the whole platform.', 'organization' => 'here is your organization training overview.'][$role] ?></p></div>
<?php foreach ($ann as $a): ?><div class="flash"><span>📣 <b><?= e($a['title']) ?></b> — <?= e($a['body']) ?></span><button onclick="this.parentNode.remove()">×</button></div><?php endforeach; ?>

<?php if ($role === 'learner'):
  $my = all("SELECT c.*, e.status es, e.completed_at FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.id DESC", [$id]);
  $act = array_filter($my, fn($c) => $c['es'] === 'active'); $comp = array_filter($act, fn($c) => $c['completed_at']);
  $certs = one("SELECT COUNT(*) c FROM certificates WHERE user_id=?", [$id])['c'];
  $up = all("SELECT a.*, c.title ct FROM assignments a JOIN courses c ON c.id=a.course_id JOIN enrollments e ON e.course_id=c.id AND e.user_id=? AND e.status='active' WHERE (a.deadline IS NULL OR a.deadline>NOW()) AND a.id NOT IN (SELECT assignment_id FROM submissions WHERE user_id=?) ORDER BY a.deadline LIMIT 5", [$id, $id]);
  $rec = all("SELECT c.*, k.name cat, (SELECT ROUND(AVG(rating),1) FROM reviews WHERE course_id=c.id) rt FROM courses c LEFT JOIN categories k ON k.id=c.category_id WHERE c.status='approved' AND (c.org_id IS NULL OR c.org_id=?) AND c.id NOT IN (SELECT course_id FROM enrollments WHERE user_id=?) ORDER BY (c.category_id IN (SELECT category_id FROM courses WHERE id IN (SELECT course_id FROM enrollments WHERE user_id=?))) DESC, rt DESC LIMIT 3", [(int)org_of($u), $id, $id]); ?>
<div class="cards"><?php kpi('📚', count($act), 'Enrolled courses', true); kpi('⏳', count($act) - count($comp), 'In progress'); kpi('✅', count($comp), 'Completed'); kpi('🎓', $certs, 'Certificates'); ?></div>
<div class="cols"><div>
 <div class="card"><h3>My courses <a class="btn btn-sm btn-outline" href="mycourses.php">View all</a></h3>
  <?php foreach (array_slice($my, 0, 5) as $c): $pg = $c['es'] === 'active' ? progress($id, $c['id']) : 0; ?>
   <div style="padding:12px 0;border-bottom:1px solid var(--line)"><div style="display:flex;justify-content:space-between;gap:10px"><b><?= e($c['title']) ?></b><span class="badge <?= $c['es'] === 'pending' ? 'warn' : ($pg >= 100 ? '' : 'grey') ?>"><?= $c['es'] === 'pending' ? 'Pending' : ($pg >= 100 ? 'Completed' : 'In Progress') ?></span></div>
   <div class="bar" style="margin:8px 0 4px"><i style="width:<?= $pg ?>%"></i></div><div style="display:flex;justify-content:space-between"><small class="muted"><?= $pg ?>%</small><a href="learn.php?course=<?= $c['id'] ?>">Continue →</a></div></div>
  <?php endforeach; if (!$my) echo '<div class="empty">You have not enrolled yet. <a href="courses.php">Browse courses</a></div>'; ?></div>
 <div class="card"><h3>Recommended for you</h3><div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(200px,1fr))"><?php foreach ($rec as $c): ?><div class="feat" style="padding:16px"><h3 style="font-size:15px"><?= e($c['title']) ?></h3><p style="font-size:13px"><?= e($c['cat']) ?> · <?= e($c['level']) ?></p><a class="btn btn-sm" style="margin-top:8px" href="course.php?id=<?= $c['id'] ?>">View</a></div><?php endforeach; if (!$rec) echo '<p class="muted">You are enrolled in everything available!</p>'; ?></div></div>
</div><div>
 <div class="card"><h3>Upcoming assignments</h3><?php foreach ($up as $a): ?><div style="padding:10px 0;border-bottom:1px solid var(--line)"><a href="assignment.php?id=<?= $a['id'] ?>"><b><?= e($a['title']) ?></b></a><br><small class="muted"><?= e($a['ct']) ?> · due <?= $a['deadline'] ? fdate($a['deadline']) : '—' ?></small></div><?php endforeach; if (!$up) echo '<p class="muted">Nothing due 🎉</p>'; ?></div>
 <div class="card"><h3>📡 Live classes <a class="btn btn-sm btn-outline" href="live.php">View all</a></h3><?php $lvx = live_upcoming($u, 3); foreach ($lvx as $L): $lst = live_state($L); ?><div style="padding:10px 0;border-bottom:1px solid var(--line)"><a href="live.php"><b><?= e($L['title']) ?></b></a> <?= $lst === 'live' ? '<span class="badge bad"><i class="dot"></i> LIVE</span>' : '' ?><br><small class="muted"><?= e($L['ct']) ?> · <?= date('D d M, H:i', strtotime($L['start_at'])) ?></small></div><?php endforeach; if (!$lvx) echo '<p class="muted">No live classes scheduled.</p>'; ?></div>
 <div class="card"><h3>Upcoming exams</h3><?php $ex = all("SELECT z.*, c.title ct FROM quizzes z JOIN courses c ON c.id=z.course_id JOIN enrollments e ON e.course_id=c.id AND e.user_id=? AND e.status='active' WHERE z.type='exam' AND z.id NOT IN (SELECT quiz_id FROM attempts WHERE user_id=? AND passed=1)", [$id, $id]); foreach ($ex as $z): ?><div style="padding:8px 0"><a href="quiz.php?id=<?= $z['id'] ?>"><b><?= e($z['title']) ?></b></a><br><small class="muted"><?= e($z['ct']) ?></small></div><?php endforeach; if (!$ex) echo '<p class="muted">No pending exams.</p>'; ?></div>
</div></div>

<?php elseif ($role === 'instructor' || $role === 'organization'):
  $sc = $role === 'organization' ? "c.org_id=$id" : "c.instructor_id=$id";
  $cs = all("SELECT c.*, (SELECT COUNT(*) FROM enrollments WHERE course_id=c.id AND status='active') n, (SELECT COUNT(*) FROM enrollments WHERE course_id=c.id AND completed_at IS NOT NULL) d, (SELECT ROUND(AVG(rating),1) FROM reviews WHERE course_id=c.id) rt FROM courses c WHERE $sc ORDER BY c.id DESC");
  $ln = array_sum(array_column($cs, 'n')); $dn = array_sum(array_column($cs, 'd'));
  $pend = one("SELECT COUNT(*) c FROM submissions s JOIN assignments a ON a.id=s.assignment_id JOIN courses c ON c.id=a.course_id WHERE $sc AND s.marks IS NULL")['c'];
  $mem = $role === 'organization' ? one("SELECT COUNT(*) c FROM users WHERE org_id=?", [$id])['c'] : null;
  $qn = all("SELECT m.*, u.name, c.title FROM comments m JOIN courses c ON c.id=m.course_id JOIN users u ON u.id=m.user_id WHERE $sc AND m.user_id<>? ORDER BY m.id DESC LIMIT 5", [$id]); ?>
<div class="cards"><?php kpi('📚', count($cs), 'Courses', true); kpi('👥', $ln, 'Enrolled learners'); kpi('✅', $ln ? round($dn * 100 / $ln).'%' : '0%', 'Completion rate'); kpi('📝', $pend, 'Submissions to grade'); if ($mem !== null) { kpi('🏢', $mem, 'Organization members'); $sb = org_sub($id); kpi('💎', $sb ? max(0, (int)ceil((strtotime($sb['end_at']) - time()) / 86400)).' days' : '—', 'Subscription left'); } ?></div>
<div class="cols"><div class="card"><h3>My courses <a class="btn btn-sm" href="course_edit.php?new=1">+ New course</a></h3><div class="tw"><table><tr><th>Course</th><th>Status</th><th>Learners</th><th>Done</th><th>Rating</th></tr>
 <?php foreach ($cs as $c): ?><tr><td><a href="course_edit.php?id=<?= $c['id'] ?>"><b><?= e($c['title']) ?></b></a></td><td><span class="badge <?= $c['status'] === 'approved' ? '' : ($c['status'] === 'pending' ? 'warn' : 'bad') ?>"><?= $c['status'] ?></span></td><td><?= $c['n'] ?></td><td><?= $c['d'] ?></td><td><?= $c['rt'] ?: '—' ?></td></tr><?php endforeach; ?></table></div><?php if (!$cs) echo '<div class="empty">No courses yet.</div>'; ?></div>
<div class="card"><h3>📡 Live classes <a class="btn btn-sm btn-outline" href="live.php">View all</a></h3><?php $lvx = live_upcoming($u, 3); foreach ($lvx as $L): $lst = live_state($L); ?><div style="padding:10px 0;border-bottom:1px solid var(--line)"><a href="live.php"><b><?= e($L['title']) ?></b></a> <?= $lst === 'live' ? '<span class="badge bad"><i class="dot"></i> LIVE</span>' : '' ?><br><small class="muted"><?= e($L['ct']) ?> · <?= date('D d M, H:i', strtotime($L['start_at'])) ?></small></div><?php endforeach; if (!$lvx) echo '<p class="muted">No live classes scheduled.</p>'; ?></div>
 <div class="card"><h3>Learner questions</h3><?php foreach ($qn as $m): ?><div style="padding:8px 0;border-bottom:1px solid var(--line)"><b><?= e($m['name']) ?></b> <small class="muted">in <?= e($m['title']) ?></small><p style="color:var(--ink)"><?= e($m['body']) ?></p></div><?php endforeach; if (!$qn) echo '<p class="muted">No questions yet.</p>'; ?></div></div>

<?php else: // admin
  $c1 = fn($sql) => one($sql)['c']; ?>
<div class="cards"><?php kpi('👥', $c1("SELECT COUNT(*) c FROM users"), 'Total users', true); kpi('🧑‍🎓', $c1("SELECT COUNT(*) c FROM users WHERE role='learner'"), 'Learners'); kpi('👨‍🏫', $c1("SELECT COUNT(*) c FROM users WHERE role='instructor'"), 'Instructors'); kpi('📚', $c1("SELECT COUNT(*) c FROM courses"), 'Total courses'); kpi('🟢', $c1("SELECT COUNT(*) c FROM courses WHERE status='approved'"), 'Active courses'); kpi('✅', $c1("SELECT COUNT(*) c FROM enrollments WHERE completed_at IS NOT NULL"), 'Completed enrollments'); kpi('🎓', $c1("SELECT COUNT(*) c FROM certificates"), 'Certificates issued'); kpi('🏢', $c1("SELECT COUNT(*) c FROM users WHERE role='organization' AND org_status='pending'"), 'Organizations to approve'); kpi('💰', money($c1("SELECT COALESCE(SUM(amount),0) c FROM payments WHERE status='paid'")), 'Revenue'); kpi('⏳', $c1("SELECT COUNT(*) c FROM payments WHERE status='pending'"), 'Payments to confirm'); ?></div>
<?php $pc = all("SELECT c.*, u.name FROM courses c JOIN users u ON u.id=c.instructor_id WHERE c.status='pending'"); $ra = all("SELECT 'enrolled in' w, u.name, c.title t, e.enrolled_at d FROM enrollments e JOIN users u ON u.id=e.user_id JOIN courses c ON c.id=e.course_id UNION ALL SELECT 'joined as', name, role, created_at FROM users ORDER BY d DESC LIMIT 8"); ?>
<div class="cols"><div class="card"><h3>Courses awaiting approval <a class="btn btn-sm btn-outline" href="admin.php?tab=courses">Manage</a></h3>
 <?php foreach ($pc as $c): ?><div style="padding:10px 0;border-bottom:1px solid var(--line)"><b><?= e($c['title']) ?></b> <small class="muted">by <?= e($c['name']) ?></small></div><?php endforeach; if (!$pc) echo '<p class="muted">All caught up ✅</p>'; ?></div>
<div class="card"><h3>System activity</h3><?php foreach ($ra as $r): ?><div style="padding:8px 0;border-bottom:1px solid var(--line);font-size:14px"><b><?= e($r['name']) ?></b> <?= e($r['w']) ?> <?= e($r['t']) ?><br><small class="muted"><?= fdate($r['d'], true) ?></small></div><?php endforeach; ?></div></div>
<?php endif; include 'includes/footer.php'; ?>
